'use client'

import Link from 'next/link'
import { usePathname } from 'next/navigation'
import { useTransition } from 'react'
import { Star } from 'lucide-react'
import {
  SidebarGroup,
  SidebarGroupLabel,
  SidebarMenu,
  SidebarMenuButton,
  SidebarMenuItem,
} from '@/components/ui/sidebar'
import { PlanBadge } from '@/components/shared/PlanBadge'
import type { NavGroup, DynamicBadgeKey } from '@/components/app/sidebar/nav-config'
import { hasFeature } from '@/lib/billing/feature-gate'
import type { PlanTier } from '@/lib/billing/feature-gate'
import { cn } from '@/lib/utils'
import { pinItemAction } from '@/app/actions/pinned-items'
import { toast } from 'sonner'

export type DynamicBadgeCounts = Partial<Record<DynamicBadgeKey, number>>

interface SidebarNavGroupProps {
  group: NavGroup
  plan: PlanTier
  isFirst?: boolean
  dynamicBadges?: DynamicBadgeCounts
}

/**
 * S17 — Updated for v2 sidebar:
 *  - Supports null label (unlabeled group skips <SidebarGroupLabel>)
 *  - Renders new badge types: count (gray pill), dot (red 6px circle), new (emerald outline)
 *  - Consumes dynamic badge counts from server-passed props
 *
 * Visual DNA (S13 tokens):
 *  - Item height: 32px (h-8)
 *  - Icons: 16px (size-4)
 *  - Icon→label gap: 8px (gap-2)
 *  - Label: 13px / font-weight 500
 *  - Section headers: 11px uppercase tracking-wider
 *  - Active state: full bg fill (bg-primary/10 text-primary) — Notion pattern
 */
function NavItemPin({ label, href, iconName }: { label: string; href: string; iconName: string | null }) {
  const [pending, startTransition] = useTransition()

  function handlePin(e: React.MouseEvent) {
    e.preventDefault()
    e.stopPropagation()
    startTransition(async () => {
      try {
        await pinItemAction({ kind: 'nav', target: href, label, href, icon: iconName })
        toast.success(`Pinned "${label}"`)
      } catch (err) {
        toast.error(err instanceof Error ? err.message : 'Failed to pin')
      }
    })
  }

  return (
    <button
      type="button"
      aria-label={`Pin ${label}`}
      onClick={handlePin}
      disabled={pending}
      className={cn(
        'absolute right-1 hidden h-6 w-6 shrink-0 items-center justify-center rounded',
        'text-muted-foreground/30 transition-colors',
        'hover:bg-rust-tint hover:text-rust',
        'group-hover/item:flex',
        'focus-visible:flex focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring',
        'group-data-[collapsible=icon]:hidden',
      )}
    >
      <Star className="h-3 w-3" aria-hidden="true" />
    </button>
  )
}

export function SidebarNavGroup({ group, plan, isFirst, dynamicBadges = {} }: SidebarNavGroupProps) {
  const pathname = usePathname()

  return (
    <SidebarGroup className={cn('px-0', isFirst ? 'pt-0' : 'pt-4')}>
      {group.label !== null && (
        <SidebarGroupLabel className="mb-1 px-2.5 text-[10px] font-bold uppercase tracking-[0.12em] text-stone-brand/70 group-data-[collapsible=icon]:hidden">
          {group.label}
        </SidebarGroupLabel>
      )}
      <SidebarMenu className="gap-0.5">
        {group.items.map((item) => {
          const isActive =
            item.href === '/dashboard'
              ? pathname === item.href
              : pathname === item.href || pathname.startsWith(item.href + '/')

          // S18 fix — plan gating is badge-only (no redirect/block).
          // `isPlanLocked` drives the informational "STUDIO" / "PRO" pill so users
          // know a feature is above their plan, but clicking still navigates. Page-
          // level or contextual gates inside the feature (if any) handle upsell.
          const isPlanLocked =
            !!item.requiredPlan &&
            !hasFeature(plan, item.featureKey ?? item.requiredPlan)

          // Resolve dynamic badge count
          const dynamicCount = item.dynamicBadge !== undefined ? (dynamicBadges[item.dynamicBadge] ?? 0) : 0

          // Decide which badge to show. Plan badge takes priority over dynamic
          // count/dot/new badges so the sidebar doesn't render two badges side-by-
          // side on a gated item.
          const showPlanBadge = isPlanLocked && !!item.requiredPlan && item.requiredPlan !== 'solo'
          const showCountBadge = !showPlanBadge && item.badgeType === 'count' && dynamicCount > 0
          const showDotBadge = !showPlanBadge && item.badgeType === 'dot' && dynamicCount > 0
          const showNewBadge = !showPlanBadge && item.badgeType === 'new'

          // Resolve icon display name for pin storage
          const iconName = (item.icon as { displayName?: string }).displayName ?? item.icon.name ?? null

          function formatCount(n: number): string {
            if (n >= 1000) return `${(n / 1000).toFixed(1)}k`
            return String(n)
          }

          return (
            <SidebarMenuItem key={item.href} className="group/item relative">
              <SidebarMenuButton
                render={<Link href={item.href} prefetch />}
                isActive={isActive}
                className={cn(
                  'relative h-8 gap-2 rounded-md px-2.5 text-[13px] font-medium transition-all duration-150',
                  'text-sidebar-foreground/85 hover:bg-sidebar-accent/40 hover:text-sidebar-foreground',
                  'data-[active=true]:bg-primary/10 data-[active=true]:text-primary data-[active=true]:font-semibold',
                )}
                tooltip={item.label}
              >
                <item.icon
                  className={cn(
                    '!h-[17px] !w-[17px] shrink-0 transition-colors',
                    isActive
                      ? 'text-primary'
                      : 'text-sidebar-foreground group-hover/item:text-sidebar-foreground',
                  )}
                  strokeWidth={2.25}
                  aria-hidden="true"
                />
                <span className="truncate group-data-[collapsible=icon]:hidden">
                  {item.label}
                </span>

                {/* Plan badge — shown when the feature is above the user's plan.
                    Visual hint only — the item is still clickable and the page
                    loads (no redirect). User-facing restrictions will land in S19. */}
                {showPlanBadge && item.requiredPlan && (
                  <PlanBadge
                    plan={item.requiredPlan}
                    className="ml-auto group-data-[collapsible=icon]:hidden"
                  />
                )}

                {/* Count badge — gray pill with number */}
                {showCountBadge && (
                  <span
                    className="ml-auto inline-flex min-w-[20px] items-center justify-center rounded-full bg-muted px-1.5 py-0.5 text-[10px] font-semibold tabular-nums text-muted-foreground group-data-[collapsible=icon]:hidden"
                    aria-label={`${dynamicCount} items`}
                  >
                    {formatCount(dynamicCount)}
                  </span>
                )}

                {/* Dot badge — 6px red circle for alerts */}
                {showDotBadge && (
                  <span
                    className="ml-auto flex h-2 w-2 shrink-0 rounded-full bg-destructive group-data-[collapsible=icon]:hidden"
                    aria-label="Alert"
                  />
                )}

                {/* New badge — Rust outline label (brand 5% accent) */}
                {showNewBadge && (
                  <span
                    className="ml-auto inline-flex items-center rounded-sm border border-rust/40 bg-rust-tint px-1.5 py-0.5 text-[9px] font-bold uppercase tracking-[0.08em] text-rust group-data-[collapsible=icon]:hidden"
                  >
                    NEW
                  </span>
                )}
              </SidebarMenuButton>

              {/* S22: hover-reveal star pin button */}
              <NavItemPin label={item.label} href={item.href} iconName={iconName} />
            </SidebarMenuItem>
          )
        })}
      </SidebarMenu>
    </SidebarGroup>
  )
}

'use client'

import Link from 'next/link'
import {
  LayoutDashboard,
  Inbox,
  CalendarDays,
  Users,
  Package,
  CreditCard,
  FolderKanban,
  BarChart2,
  Sparkles,
  Megaphone,
  FileText,
  Image,
  MapPin,
  MessageSquare,
  Briefcase,
  Zap,
  Star,
  X,
} from 'lucide-react'
import type { LucideIcon } from 'lucide-react'
import { useTransition } from 'react'
import { toast } from 'sonner'
import { unpinItemAction } from '@/app/actions/pinned-items'
import { cn } from '@/lib/utils'
import type { UserPinnedItem } from '@/lib/pinned-items/pinned'

const ICON_MAP: Record<string, LucideIcon> = {
  LayoutDashboard,
  Inbox,
  CalendarDays,
  Users,
  Package,
  CreditCard,
  FolderKanban,
  BarChart2,
  Sparkles,
  Megaphone,
  FileText,
  Image,
  MapPin,
  MessageSquare,
  Briefcase,
  Zap,
  Star,
}

interface PinnedItemRowProps {
  item: UserPinnedItem
}

// Render icon by name using a stable lookup — avoids creating components during render.
function PinnedIcon({ iconName }: { iconName: string | null }) {
  const IconComponent = ICON_MAP[iconName ?? ''] ?? Star
  return <IconComponent className="h-4 w-4 shrink-0 opacity-55" aria-hidden="true" />
}

function PinnedItemRow({ item }: PinnedItemRowProps) {
  const [pending, startTransition] = useTransition()

  function handleUnpin(e: React.MouseEvent) {
    e.preventDefault()
    e.stopPropagation()
    startTransition(async () => {
      try {
        await unpinItemAction({ kind: item.kind, target: item.target })
        toast.success(`Unpinned "${item.label}"`)
      } catch {
        toast.error('Failed to unpin')
      }
    })
  }

  return (
    <div className="group/pin relative flex items-center">
      <Link
        href={item.href}
        prefetch
        className={cn(
          'flex flex-1 items-center gap-2 rounded-md px-2.5 py-1.5 text-[13px] font-medium',
          'text-sidebar-foreground/65 transition-colors hover:bg-sidebar-accent/40 hover:text-sidebar-foreground',
          'min-w-0',
        )}
      >
        <PinnedIcon iconName={item.icon} />
        <span className="truncate">{item.label}</span>
      </Link>
      <button
        type="button"
        aria-label={`Unpin ${item.label}`}
        onClick={handleUnpin}
        disabled={pending}
        className={cn(
          'absolute right-1 hidden h-5 w-5 shrink-0 items-center justify-center rounded',
          'text-muted-foreground/40 hover:bg-muted/60 hover:text-muted-foreground',
          'group-hover/pin:flex',
          'focus-visible:flex focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring',
        )}
      >
        <X className="h-3 w-3" aria-hidden="true" />
      </button>
    </div>
  )
}

interface SidebarFavoritesProps {
  pinnedItems: UserPinnedItem[]
}

export function SidebarFavorites({ pinnedItems }: SidebarFavoritesProps) {
  return (
    <div className="mx-2 my-2 group-data-[collapsible=icon]:hidden">
      {pinnedItems.length === 0 ? (
        <div className="flex flex-col items-center gap-1.5 rounded-md border border-dashed border-border/40 px-3 py-3 text-center">
          <Star className="h-3.5 w-3.5 text-muted-foreground/30" aria-hidden="true" />
          <p className="text-[11px] text-muted-foreground/40">Star items to pin them here</p>
        </div>
      ) : (
        <div className="space-y-0.5">
          <p className="mb-1 px-2.5 text-[11px] font-semibold uppercase tracking-wider text-muted-foreground/50">
            Favorites
          </p>
          {pinnedItems.map((item) => (
            <PinnedItemRow key={item.id} item={item} />
          ))}
        </div>
      )}
